// Simulate a MongoDB products collection
const products = [
  { _id: 1, name: 'Wireless Headphones', price: 2499, category: 'Electronics', inStock: true },
  { _id: 2, name: 'USB-C Hub', price: 1299, category: 'Electronics', inStock: true },
  { _id: 3, name: 'Mouse Pad', price: 299, category: 'Accessories', inStock: true },
  { _id: 4, name: 'Laptop Stand', price: 899, category: 'Accessories', inStock: false },
  { _id: 5, name: 'Mechanical Keyboard', price: 3499, category: 'Electronics', inStock: true },
];

// Simulate find() with filter
function find(collection, filter = {}) {
  return collection.filter(doc =>
    Object.entries(filter).every(([key, value]) => {
      if (typeof value === 'object' && value !== null) {
        if ('$gt' in value) return doc[key] > value.$gt;
        if ('$gte' in value) return doc[key] >= value.$gte;
        if ('$lt' in value) return doc[key] < value.$lt;
        if ('$in' in value) return value.$in.includes(doc[key]);
      }
      return doc[key] === value;
    })
  );
}

// Try different queries:
console.log('In-stock items:', find(products, { inStock: true }).map(p => p.name));
console.log('Electronics:', find(products, { category: 'Electronics' }).map(p => p.name));
console.log('Price > 1000:', find(products, { price: { $gt: 1000 } }).map(p => p.name));
console.log('Multiple categories:', find(products, { category: { $in: ['Electronics', 'Accessories'] } }).map(p => p.name));
